#include "exotic/cognition/temporal_agency.hpp"
#include <cassert>
using namespace exotic::cognition;
int main(){TemporalAgency t;const std::int64_t now=100000;Intention future{"future","future project","c1","committed",.8,"chosen"};Intention urgent{"urgent","deadline work","c2","committed",.8,"chosen"};Intention recurring{"recurring","revisit question","c3","tentative",.6,"available"};Intention interrupted{"interrupted","continue investigation","c4","suspended",.7,"paused"};Intention inactive{"done","completed","c5","completed",1,"done"};auto d=t.consider({{future,now+5000,0,0,0,.2,.8,0,false},{urgent,0,now+600,0,0,.8,.4,0,false},{recurring,0,0,now-10000,3600,.3,.5,0,false},{interrupted,0,0,now-100,0,.4,.6,.8,true},{inactive,0,0,0,0,1,1,0,false}},now);assert(d.size()==5);assert(d[0].choice==TemporalChoice::Later);assert(d[1].choice==TemporalChoice::Now);assert(d[2].choice==TemporalChoice::Resume);assert(d[3].choice==TemporalChoice::Resume);assert(d[4].choice==TemporalChoice::Skip);assert(future.state=="committed");assert(interrupted.state=="suspended");auto empty=t.consider({},now);assert(empty.empty());return 0;}
